224:     /// When a line of live text was spoken: the provider's time when it agrees with
225:     /// when the line arrived here (within 10 minutes), else the arrival time.
226:     nonisolated static func spokenAt(_ message: GuestMeetingMessage) -> Date? {
227:         guard let received = message.receivedAt else { return message.sentAt }
228:         guard let sent = message.sentAt, abs(sent.timeIntervalSince(received)) <= 600 else { return received }
