110:     private static func precedes(_ a: TranscriptSegment, _ b: TranscriptSegment) -> Bool {
111:         switch (a.spokenAt, b.spokenAt) {
112:         case let (x?, y?): return x == y ? a.id < b.id : x < y
113:         case (nil, _?): return false
114:         case (_?, nil): return true
115:         case (nil, nil): return a.id < b.id
