119:     public mutating func upsert(_ incoming: [TranscriptSegment]) {
120:         var changes: [String: TranscriptSegment] = [:]
121:         for segment in incoming where !segment.id.isEmpty && !segment.text.isEmpty && shouldRetain(id: segment.id, spokenAt: segment.spokenAt) {
122:             changes[segment.id] = segment
123:         }
124:         changes = changes.filter { segmentsByID[$0.key] != $0.value }
125:         guard !changes.isEmpty else { return }
126:         let additions = changes.values.sorted(by: Self.precedes)
127:         let previous = segments.filter { changes[$0.id] == nil }
128:         // Merge ordered deltas instead of sorting the full retained transcript.
129:         var merged: [TranscriptSegment] = []
130:         merged.reserveCapacity(previous.count + additions.count)
131:         var left = 0, right = 0
132:         while left < previous.count && right < additions.count {
133:             if Self.precedes(previous[left], additions[right]) { merged.append(previous[left]); left += 1 }
134:             else { merged.append(additions[right]); right += 1 }
135:         }
136:         merged.append(contentsOf: previous[left...]); merged.append(contentsOf: additions[right...])
137:         if merged.count > 5_000 { isTruncated = true }
138:         segments = Array(merged.suffix(5_000))
139:         for (id, value) in changes { segmentsByID[id] = value }
140:         for removed in merged.prefix(max(0, merged.count - 5_000)) { segmentsByID.removeValue(forKey: removed.id) }
141:     }
