4: /// Submission enters history first; visual feedback waits for transport
5: /// acceptance. Session invalidation drops every outstanding completion.
6: @MainActor
7: final class ReactionSubmission {
8:     var onAccepted: ((MeetingReaction, String) -> Void)?
9:     var onTransmitted: ((MeetingReaction, String) -> Void)?
10:     var onFailed: ((String) -> Void)?
11:     private struct Pending { let kind: MeetingReaction; var submitted = false; var result: Bool? }
12:     private var pending: [String: Pending] = [:]
13:     private var stopped = false
14:     private let valid: () -> Bool
15:     init(valid: @escaping () -> Bool) { self.valid = valid }
