17:     func send(_ kind: MeetingReaction, using submit: (@escaping (Bool) -> Void) -> Bool) -> Bool {
18:         guard !stopped, valid() else { return false }
19:         let id = UUID().uuidString
20:         pending[id] = Pending(kind: kind)
21:         guard submit({ [weak self] result in self?.complete(id, result: result) }), !stopped, valid() else {
22:             pending.removeValue(forKey: id); return false
23:         }
24:         onAccepted?(kind, id)
25:         guard var entry = pending[id] else { return true }
26:         entry.submitted = true; pending[id] = entry
27:         if let result = entry.result { complete(id, result: result) }
28:         return true
29:     }
30:     private func complete(_ id: String, result: Bool) {
31:         guard !stopped, valid(), var entry = pending[id] else { pending.removeValue(forKey: id); return }
32:         guard entry.submitted else { entry.result = result; pending[id] = entry; return }
33:         pending.removeValue(forKey: id)
34:         if result { onTransmitted?(entry.kind, id) } else { onFailed?(id) }
35:     }
36:     func stop() { stopped = true; pending = [:]; onAccepted = nil; onTransmitted = nil; onFailed = nil }
